use elevenlabs_rust_sdk::*;

#[test]
fn get_speech_history_response_round_trips_through_serde() {
    let wire = serde_json::from_str::<serde_json::Value>(
        r#"{
        "history": [
            {
                "history_item_id": "value",
                "request_id": "value",
                "voice_id": "value",
                "model_id": "value",
                "voice_name": "value",
                "voice_category": "premade",
                "text": "value",
                "date_unix": 123,
                "character_count_change_from": 123,
                "character_count_change_to": 123,
                "content_type": "value",
                "state": {},
                "settings": {},
                "share_link_id": "value",
                "source": "TTS",
                "alignments": {
                    "alignment": {
                        "characters": [
                            "value"
                        ],
                        "character_start_times_seconds": [
                            9.99
                        ],
                        "character_end_times_seconds": [
                            9.99
                        ]
                    },
                    "normalized_alignment": {
                        "characters": [
                            "value"
                        ],
                        "character_start_times_seconds": [
                            9.99
                        ],
                        "character_end_times_seconds": [
                            9.99
                        ]
                    }
                },
                "dialogue": [
                    {
                        "text": "value",
                        "voice_id": "value",
                        "voice_name": "value"
                    }
                ],
                "output_format": "value"
            }
        ],
        "last_history_item_id": "value",
        "has_more": true,
        "scanned_until": 123
    }"#,
    )
    .expect("fixture is valid JSON");
    let decoded: GetSpeechHistoryResponse =
        serde_json::from_value(wire.clone()).expect("wire value should deserialize");
    assert_eq!(
        serde_json::to_value(&decoded).expect("model should serialize"),
        wire
    );
}

